Here is an example code for a TCP IP server in C:

```c
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    // Create a socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Socket creation failed");
        return -1;
    }

    // Set up the address
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8888);

    // Bind the socket to the address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address))<0) {
        perror("Bind failed");
        return -1;
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        return -1;
    }

    // Accept incoming connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen))<0) {
        perror("Accept failed");
        return -1;
    }

    // Read data from client
    read(new_socket, buffer, 1024);
    printf("Client: %s\n", buffer);

    // Send a response to client
    char *message = "Hello from server";
    send(new_socket, message, strlen(message), 0);
    printf("Server: Hello message sent\n");

    return 0;
}
```

This code creates a TCP IP server that listens on port 8888 for incoming connections. It accepts a connection from a client, reads a message from the client, and sends a response back to the client.

